; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 21: Cls
			dw kw_cls

			; 22: Print "VB self test 6"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 25: For i = 0 To 9
			dw kw_ztov, var_i
for1_t:

			; 26: buf(i) = i * 30
			dw kw_mulvl, var_i, 30, tmp1
			dw kw_aset8, arr_buf, var_i, tmp1

			; 27: Next
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; 28: Chk buf(9), 14          ' 270 And 255
			dw kw_lptrtov8, arr_buf+9, tmp0
			dw p_chk_c, tmp0, lit_14

			; 29: Chk buf(2), 60
			dw kw_lptrtov8, arr_buf+2, tmp0
			dw p_chk_c, tmp0, lit_60

			; 30: i = 3
			dw kw_ltov, 3, var_i

			; 31: Chk buf(i), 90
			dw kw_aget8, arr_buf, var_i, tmp0
			dw p_chk_c, tmp0, lit_90

			; 32: buf(0) = 255
			dw kw_ltolptr8, 255, arr_buf

			; 33: Chk buf(0), 255
			dw kw_lptrtov8, arr_buf, tmp0
			dw p_chk_c, tmp0, lit_255

			; 34: Chk ByteSum(buf), 255 + 30 + 60 + 90 + 120 + 150 + 180 + 210 + 240 + 14
			dw p_bytesum_c, ad_arr_buf
			dw p_chk_c, var_bytesum_bytesum, lit_1349

			; 37: ReDim dyn(5)
			dw kw_redim, pa_dyn, pa_dyn_data, 0, 2, 6, 1

			; 38: Chk UBound(dyn), 5
			dw kw_ubound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_5

			; 39: Chk LBound(dyn), 0
			dw kw_lbound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_0

			; 40: For i = 0 To 5
			dw kw_ztov, var_i
for2_t:

			; 41: dyn(i) = i * i
			dw kw_mulvv, var_i, var_i, tmp2
			dw kw_pset, pa_dyn, var_i, tmp2

			; 42: Next
			dw kw_next1l_n, var_i, 5, for2_t
for2_e:

			; 43: Chk dyn(5), 25
			dw kw_pget, pa_dyn, lit_5, tmp0
			dw p_chk_c, tmp0, lit_25

			; 44: ReDim Preserve dyn(BIGN)
			dw kw_redim, pa_dyn, pa_dyn_data, 0, 2, 21, 0

			; 45: Chk UBound(dyn), 20
			dw kw_ubound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_20

			; 46: Chk dyn(4), 16
			dw kw_pget, pa_dyn, lit_4, tmp0
			dw p_chk_c, tmp0, lit_16

			; 47: dyn(20) = 7
			dw kw_pset, pa_dyn, lit_20, lit_7

			; 48: Chk dyn(20), 7
			dw kw_pget, pa_dyn, lit_20, tmp0
			dw p_chk_c, tmp0, lit_7

			; 49: ReDim dyn(1 To 3)
			dw kw_redim, pa_dyn, pa_dyn_data, 1, 2, 3, 1

			; 50: Chk LBound(dyn), 1
			dw kw_lbound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_1

			; 51: Chk dyn(1), 0           ' cleared without Preserve
			dw kw_pget, pa_dyn, lit_1, tmp0
			dw p_chk_c, tmp0, lit_0

			; 52: dyn(3) = 9
			dw kw_pset, pa_dyn, lit_3, lit_9

			; 53: Chk Total(dyn), 9
			dw p_total_c, pa_dyn
			dw p_chk_c, var_total_total, lit_9

			; 54: Erase dyn
			dw kw_redim, pa_dyn, pa_dyn_data, 0, 2, 0, 0

			; 55: Chk UBound(dyn), -1
			dw kw_ubound, pa_dyn, tmp0
			dw p_chk_c, tmp0, lit_m1

			; 57: ReDim names(2)
			dw kw_redim, pa_names, pa_names_data, 0, 41, 3, 1

			; 58: names(1) = "dyn"
			dw kw_psets, pa_names, lit_1, str1

			; 59: Chk Len(names(1)), 3
			dw kw_pget, pa_names, lit_1, stmp0
			dw kw_strlen, stmp0, tmp0
			dw p_chk_c, tmp0, lit_3

			; 60: ReDim big(1)
			dw kw_redim, pa_big, pa_big_data, 0, 4, 2, 1

			; 61: big(1) = 100000
			dw kw_pset, pa_big, lit_1, llit_100000

			; 62: Chk big(1) \ 1000, 100
			dw kw_pget, pa_big, lit_1, ltmp0
			dw kw_l_div, ltmp0, llit_1000, ltmp0
			dw kw_l_ltoi, ltmp0, tmp0
			dw p_chk_c, tmp0, lit_100

			; 65: fixed(2) = 5
			dw kw_ltov, 5, arr_fixed+4

			; 66: Erase fixed
			dw kw_erase, arr_fixed, 10

			; 67: Chk fixed(2), 0
			dw p_chk_c, arr_fixed+4, lit_0

			; 70: ReDim recs(2)
			dw kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 3, 1
			dw kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 3, 1

			; 71: For i = 0 To 2
			dw kw_ztov, var_i
for3_t:

			; 72: recs(i).n = i * 5
			dw kw_mulvl, var_i, 5, tmp2
			dw kw_pset, pa_recs_n, var_i, tmp2

			; 73: recs(i).nm = "r" & i
			dw kw_strcstr, stmp3, var_i
			dw kw_strcpy, stmp2, str2
			dw kw_strcat, stmp2, stmp3
			dw kw_psets, pa_recs_nm, var_i, stmp2

			; 74: Next
			dw kw_next1l_n, var_i, 2, for3_t
for3_e:

			; 75: Chk UBound(recs), 2
			dw kw_ubound, pa_recs_n, tmp0
			dw p_chk_c, tmp0, lit_2

			; 76: Chk Len(recs(1).nm) + recs(2).n, 12
			dw kw_pget, pa_recs_nm, lit_1, stmp0
			dw kw_strlen, stmp0, tmp0
			dw kw_pget, pa_recs_n, lit_2, tmp1
			dw kw_add, tmp0, tmp1, tmp0
			dw p_chk_c, tmp0, lit_12

			; 77: ReDim Preserve recs(4)
			dw kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 5, 0
			dw kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 5, 0

			; 78: Chk recs(2).n, 10
			dw kw_pget, pa_recs_n, lit_2, tmp0
			dw p_chk_c, tmp0, lit_10

			; 79: Erase recs
			dw kw_redim, pa_recs_n, pa_recs_n_data, 0, 2, 0, 0
			dw kw_redim, pa_recs_nm, pa_recs_nm_data, 0, 41, 0, 0

			; 80: Chk UBound(recs), -1
			dw kw_ubound, pa_recs_n, tmp0
			dw p_chk_c, tmp0, lit_m1

			; 82: Print
			dw kw_printnl

			; 83: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printstrvar, str3
			dw kw_printint, var_bad
			dw kw_printstrvar, str4
			dw kw_printnl

			; 84: End
			dw kw_printnl0
			dw kw_printstrvar, str5
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 87: t = t + 1
			dw kw_inc, var_t

			; 88: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str6

			; 89: If got = want Then
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if4_1

			; 90: Print "ok ";
			dw kw_printstrvar, str7

			; 91: Else
			dw if4_e_go
if4_1:

			; 92: Print "FAIL("; got; ") ";
			dw kw_printstrvar, str8
			dw kw_printint, var_chk_got
			dw kw_printstrvar, str9

			; 93: bad = bad + 1
			dw kw_inc, var_bad

			; 94: End If
if4_e:
			dw p_chk_r

; ============================================================
; function bytesum (normal mode)
; ============================================================

p_bytesum:

			; 98: Dim k As Integer

			; 99: ByteSum = 0
			dw kw_ztov, var_bytesum_bytesum

			; 100: For k = LBound(b) To UBound(b)
			dw kw_lbound, pa_bytesum_b, var_bytesum_k
			dw kw_ubound, pa_bytesum_b, for5_l
			dw kw_forupv_n, var_bytesum_k, for5_l, for5_e
for5_t:

			; 101: ByteSum = ByteSum + b(k)
			dw kw_ztov, tmp1
			dw kw_pget, pa_bytesum_b, var_bytesum_k, tmp1
			dw kw_add, var_bytesum_bytesum, tmp1, var_bytesum_bytesum

			; 102: Next
			dw kw_next1v_n, var_bytesum_k, for5_l, for5_t
for5_e:
			dw p_bytesum_r

; ============================================================
; function total (normal mode)
; ============================================================

p_total:

			; 106: Dim k As Integer

			; 107: Total = 0
			dw kw_ztov, var_total_total

			; 108: For k = LBound(a) To UBound(a)
			dw kw_lbound, pa_total_a, var_total_k
			dw kw_ubound, pa_total_a, for6_l
			dw kw_forupv_n, var_total_k, for6_l, for6_e
for6_t:

			; 109: Total = Total + a(k)
			dw kw_pget, pa_total_a, var_total_k, tmp1
			dw kw_add, var_total_total, tmp1, var_total_total

			; 110: Next
			dw kw_next1v_n, var_total_k, for6_l, for6_t
for6_e:
			dw p_total_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if4_e_go:			ld sp, if4_e
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_bytesum_c:		; call bytesum (normal)
			pop hl			; b() descriptor
			ld de, pa_bytesum_b
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_bytesum_bytesum), hl
			ld hl, 0
			ld (var_bytesum_k), hl
			ld (p_bytesum_rs), sp
			ld sp, p_bytesum
			jp ntc_xn
p_bytesum_r:		; end of bytesum
			ld sp, (p_bytesum_rs)
			jp ntc_xn
p_total_c:		; call total (normal)
			pop hl			; a() descriptor
			ld de, pa_total_a
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_total_total), hl
			ld hl, 0
			ld (var_total_k), hl
			ld (p_total_rs), sp
			ld sp, p_total
			jp ntc_xn
p_total_r:		; end of total
			ld sp, (p_total_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_i:			dw 0
ad_arr_buf:			dw arr_buf, 0, 0, 10, 1, 1		; array as an argument
var_bytesum_bytesum:			dw 0
var_total_total:			dw 0
var_t:			dw 0
var_bad:			dw 0
p_chk_rs:			dw 0
var_chk_got:			dw 0
var_chk_want:			dw 0
p_bytesum_rs:			dw 0
var_bytesum_k:			dw 0
for5_l:			dw 0
p_total_rs:			dw 0
var_total_k:			dw 0
for6_l:			dw 0
tmp0:			dw 0
tmp1:			dw 0
tmp2:			dw 0
			db 255			; capacity
stmp0:			ds 256
			db 255			; capacity
stmp1:			ds 256
			db 255			; capacity
stmp2:			ds 256
			db 255			; capacity
stmp3:			ds 256
ltmp0:			dw 0, 0

; numbers passed by address (read only)
lit_14:			dw 14
lit_60:			dw 60
lit_90:			dw 90
lit_255:			dw 255
lit_1349:			dw 1349
lit_5:			dw 5
lit_0:			dw 0
lit_25:			dw 25
lit_20:			dw 20
lit_4:			dw 4
lit_16:			dw 16
lit_7:			dw 7
lit_1:			dw 1
lit_9:			dw 9
lit_3:			dw 3
lit_m1:			dw -1
llit_100000:			dw 34464, 1
llit_1000:			dw 1000, 0
lit_100:			dw 100
lit_2:			dw 2
lit_12:			dw 12
lit_10:			dw 10

; ============================================================
; Strings
; ============================================================

str0:			db "VB self test 6", 0
str1:			db "dyn", 0
str2:			db "r", 0
str3:			db " tests, ", 0
str4:			db " failed", 0
str5:			db "Press a key", 0
str6:			db ":", 0
str7:			db "ok ", 0
str8:			db "FAIL(", 0
str9:			db ") ", 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_forupv_n:	jp 25
kw_next1l_n:	jp 31
kw_next1v_n:	jp 33
kw_ltov:		jp 47
kw_ztov:		jp 49
kw_inc:		jp 51
kw_add:		jp 53
kw_mulvv:	jp 60
kw_mulvl:	jp 61
kw_cpeqvv:	jp 95
kw_lptrtov8:	jp 99
kw_ltolptr8:	jp 105
kw_aget8:	jp 113
kw_aset8:	jp 114
kw_redim:	jp 115
kw_erase:	jp 116
kw_strcpy:	jp 122
kw_strcat:	jp 124
kw_strlen:	jp 125
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl0:	jp 134
kw_printnl:	jp 138
kw_cls:		jp 147
kw_strcstr:	jp 175
kw_pget:		jp 198
kw_pset:		jp 199
kw_psets:	jp 200
kw_lbound:	jp 204
kw_ubound:	jp 205
kw_l_ltoi:	jp 208
kw_l_div:	jp 229
kw_bssinit:	jp 288
kw_waitkey:	jp 348
NTC_RJ_N	equ 37		; entries
ntc_csp	equ #8800		; ROM data
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #894E		; ROM data
ntc_v_romen	equ #8954		; ROM data
ntc_v_romold	equ #8956		; ROM data
ntc_v_stamp	equ #8952		; ROM data
ntc_v_start	equ #8950		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM set in slots 0 - 31 (its main ROM, then the others with the same
; stamp), have the main one patch the jump block. NC = ready; C = not there / too old
; (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			xor a
			ld (ntc_rj_want), a
			call ntc_rj_scan		; the main ROM
			jp c, ntc_rj_nf
			ld (ntc_rj_slots), a
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, 1
ntc_rj_more:				; the other ROMs of the set
			ld (ntc_rj_want), a
			ld hl, ntc_rj_n
			cp (hl)
			jr nc, ntc_rj_all
			call ntc_rj_scan
			jp c, ntc_rj_part
			ld b, a
			ld a, (ntc_rj_want)
			ld e, a
			ld d, 0
			ld hl, ntc_rj_slots
			add hl, de
			ld (hl), b
			inc a
			jr ntc_rj_more
ntc_rj_all:
			ld a, (ntc_rj_slots)
			ld c, a
			call #B90F		; KL ROM SELECT: the main ROM
			di					; (KL ROM SELECT lets interrupts in)
			ld a, (ntc_rj_slots)	; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
			ld de, ntc_rj_slots
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot, DE = slots; C: DE = a number it hasn't got
			jp c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
; ntc_rj_scan - a ROM of the set: ROM ntc_rj_want (0 = the main one, any stamp; the others
; with the main one's stamp). NC: A = its slot, HL = past its block's count byte (the main
; one: at its patcher), it is selected. C: not there
ntc_rj_scan:
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its set's stamp
			inc hl
			ld a, (ntc_rj_want)
			cp (hl)				; its place in the set
			jr nz, ntc_rj_skip
			or a
			jr z, ntc_rj_got
			push hl
			ld hl, (ntc_rj_set)
			or a
			sbc hl, de
			pop hl
			jr nz, ntc_rj_skip		; another build's
ntc_rj_got:
			ld (ntc_rj_set), de
			inc hl
			ld a, (hl)
			ld (ntc_rj_n), a		; ROMs in the set
			inc hl
			ld a, c
			or a				; NC
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			scf					; C: not there
			ret
ntc_rj_nf:
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_part:				; a ROM of the set is missing: its number (1 = the main one)
			ld a, (ntc_rj_want)
			inc a
			ld e, a
			ld d, 0
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tpt
			jr ntc_rj_fnum
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fnum:
			ld a, 1
			ld (ntc_rj_pn), a		; the number after the message
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld a, (ntc_rj_pn)
			or a
			jr z, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_pn:		db 0			; 1 = a number goes after the message
ntc_rj_want:	db 0			; the ROM of the set looked for
ntc_rj_n:		db 1			; ROMs in the set
ntc_rj_set:		dw 0			; the set's stamp
ntc_rj_slots:	ds 8			; each ROM's slot, the main one first
ntc_rj_sig:		db "NTC", 2, "CPCFW", 0	; the ROMs' NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCFW (NTCFW.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCFW too old: no routine #", 0
ntc_rj_tpt:		db "ROM NTCFW<n>.ROM not found: n = #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
arr_buf		equ ntc_bss + 0		; 10 bytes
pa_dyn		equ ntc_bss + 10		; 12 bytes
pa_names		equ ntc_bss + 22		; 12 bytes
pa_big		equ ntc_bss + 34		; 12 bytes
arr_fixed		equ ntc_bss + 46		; 10 bytes
pa_dyn_data		equ ntc_bss + 56		; 42 bytes
pa_names_data		equ ntc_bss + 98		; 123 bytes
pa_big_data		equ ntc_bss + 221		; 8 bytes
pa_recs_n		equ ntc_bss + 229		; 12 bytes
pa_recs_n_data		equ ntc_bss + 241		; 10 bytes
pa_recs_nm		equ ntc_bss + 251		; 12 bytes
pa_recs_nm_data		equ ntc_bss + 263		; 205 bytes
pa_bytesum_b		equ ntc_bss + 468		; 12 bytes
pa_total_a		equ ntc_bss + 480		; 12 bytes
ntc_bss_size	equ 492
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "VBTEST6.BIN", ntc_start, ntc_end - ntc_start, ntc_start
